function calc(q){
  let s=q.toLowerCase().replace(/[,?!]/g,'').replace(/what is|what's|calculate|solve|compute|equals?|=/g,' ');
  let m=s.match(/(\d+(?:\.\d+)?)\s*%\s*of\s*(\d+(?:\.\d+)?)/);if(m)return +(m[1]/100*m[2]).toFixed(6);
  m=s.match(/(?:square root of|sqrt(?: of)?)\s*\(?\s*(\d+(?:\.\d+)?)/);if(m)return +Math.sqrt(m[1]).toFixed(6);
  s=s.replace(/plus/g,'+').replace(/minus/g,'-').replace(/multiplied by|times/g,'*').replace(/divided by|over/g,'/').replace(/squared/g,'^2').replace(/cubed/g,'^3').replace(/(\d)\s*x\s*(\d)/g,'$1*$2').replace(/\s+/g,'');
  if(!/^[\d+\-*/().^]+$/.test(s)||!/\d/.test(s)||!/[+\-*/^]/.test(s))return null;
  const tk=s.match(/\d+\.?\d*|[-+*/^()]/g),out=[],op=[],pr={'+':1,'-':1,'*':2,'/':2,'^':3};let prev=null;
  for(const t of tk){
    if(/\d/.test(t)){out.push(+t)}
    else if(t==='('){op.push(t)}
    else if(t===')'){while(op.length&&op[op.length-1]!=='(')out.push(op.pop());op.pop()}
    else{if(t==='-'&&(prev===null||/[-+*/^(]/.test(prev)))out.push(0);
      while(op.length&&op[op.length-1]!=='('&&(pr[op[op.length-1]]>pr[t]||(pr[op[op.length-1]]===pr[t]&&t!=='^')))out.push(op.pop());op.push(t)}
    prev=t}
  while(op.length)out.push(op.pop());
  const st=[];for(const t of out){if(typeof t==='number')st.push(t);else{const b=st.pop(),a=st.pop();if(a===undefined||b===undefined)return null;st.push(t==='+'?a+b:t==='-'?a-b:t==='*'?a*b:t==='/'?a/b:Math.pow(a,b))}}
  const r=st[0];return Number.isFinite(r)?+r.toFixed(6):null}

