const un=u=>{u=u.toLowerCase().replace(/s$/,'');return U[u]?u:(U[u+'s']?u+'s':null)};
function conv(q){
  const m=q.toLowerCase().match(/(-?\d+(?:\.\d+)?)\s*(?:°)?\s*([a-z]+)\s*(?:to|in|into|as)\s*([a-z]+)/);if(!m)return null;
  const v=+m[1],a=un(m[2]),b=un(m[3]);if(!a||!b)return null;const A=U[a],B=U[b];if(A[0]!==B[0])return null;
  let r;if(A[0]==='t'){const isC=x=>/^c/.test(x);r=isC(a)===isC(b)?v:isC(a)?v*9/5+32:(v-32)*5/9}else r=v*A[1]/B[1];
  return `📏 ${v} ${m[2]} = **${+r.toFixed(4)} ${m[3]}**`}

function search(q){const qt=toks(q);if(!qt.length)return null;let best=null,bs=0;
  for(const e of ENT){let s=0,mt=0;for(const t of qt){const k=e.keys.find(k=>same(t,k));if(k){s+=idf(k);mt++}}
    if(mt)s+=mt/qt.length+mt/e.keys.length*.6;if(s>bs){bs=s;best=e}}
  return bs>=1.9?best:null}


