const $=id=>document.getElementById(id),W=$('vcw'),M=$('vcm'),I=$('vci');const hist=[];let busy=false;
const esc=t=>t.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const fmt=t=>esc(t).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\n/g,'<br>');
function bubble(t,who,link){const d=document.createElement('div');d.className='b '+who;d.innerHTML=fmt(t);
  if(link){const a=document.createElement('a');a.textContent=link[0];a.href=link[1];const own=link[1].indexOf(P)===0;if(own){const here=location.pathname.split('/').pop()||P;if(here===P){a.href=link[1].slice(P.length)||'#'}}else if(/^https?:/.test(link[1])||/\.html/.test(link[1])){a.target='_blank';a.rel='noopener'}d.appendChild(document.createElement('br'));d.appendChild(a)}
  M.appendChild(d);M.scrollTop=M.scrollHeight}
function chips(list){$('vcc').innerHTML='';list.forEach(t=>{const b=document.createElement('button');b.textContent=t;b.onclick=()=>send(t);$('vcc').appendChild(b)})}
