$('vclcp').onclick=()=>lmCopy(lmLink(false),'Invite link copied ✅');
$('vclcc').onclick=()=>lmCopy(lmCode,'Code copied ✅');
$('vcls').onclick=()=>{window.open(lmLink(true),'_blank','noopener');lmShowCode()};
const lmJoin=()=>{const c=lmParse($('vclin').value);if(!c){$('vcle').style.color='#fda4af';$('vcle').textContent='Enter a valid code, like abc-defg-hij.';return}
  $('vcle').textContent='';window.open(MEETP+'?code='+c,'_blank','noopener')};
$('vclj').onclick=lmJoin;$('vclin').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();lmJoin()}};
